export default function AccordionDottedLine() {
	return (
		<Accordion
			type="single"
			variant="open"
			indicator="plus-minus"
			className="w-full lg:w-[75%]"
			defaultValue="2"
			collapsible>
			{contents.map((item) => (
				<AccordionItem
					className="border-dashed"
					value={item.id.toString()}
					key={item.id}>
