]

// Which of the initial files should start as uploading (not yet done)
const UPLOADING_INITIAL_IDS = new Set(["initial-marketing"])

function getFileIcon(file: FileWithPreview) {
	const f = file.file
	const type = f instanceof File ? f.type : f.type
	const name = f instanceof File ? f.name : f.name

	if (
		type.includes("word") ||
		name.endsWith(".doc") ||
		name.endsWith(".docx") ||
		name.endsWith(".pdf")
	) {
		return (
			<Image
				src="/pdf.svg"
				height={24}
				width={24}
				alt="DOCX"
				className="size-6"
			/>
		)
	} else if (
		type.startsWith("image/") ||
		name.endsWith(".png") ||
		name.endsWith(".jpg") ||
		name.endsWith(".svg")
	) {
		return (
			<Image
				src="/png.svg"
				height={24}
				width={24}
				alt="Image"
				className="size-6"
			/>
