			const parsed = parseCountry(country)
			return !preferredCountries.includes(parsed.iso2 as CountryIso2)
		})
		return { preferred, others }
	}, [preferredCountries])

	const { inputValue, handlePhoneValueChange, inputRef, country, setCountry } =
		usePhoneInput({
