					<SliderThumb />
				</Slider>

				{/* Tick marks */}
				<div className="relative mt-2 w-full px-2">
					{allMarks.map((mark) => {
						const percent = ((mark - min) / (max - min)) * 100
						const isMajor = marks.includes(mark)
						return (
							<span
								key={mark}
								className="absolute top-0 flex -translate-x-1/2 flex-col items-center"
								style={{ left: `${percent}%` }}>
								<span
