				{/* Labels */}
				<div className="relative mt-3 w-full px-2">
					{marks.map((mark) => {
						const percent = ((mark - min) / (max - min)) * 100
						return (
							<span
								key={mark}
								className="text-fg-secondary absolute -translate-x-1/2 text-xs"
								style={{ left: `${percent}%` }}>
